import {
  ModelEvaluator,
  parseRelativeValuesBundle,
} from "@quri/squiggle-relative-values/core";

import portfolioJson from "./data/portfolio.bundle.json";

// Generated by `pnpm bundle`. The bundle is validated once; the same data
// powers the dashboard and the initiative pages.
const parsed = parseRelativeValuesBundle(portfolioJson);
if (!parsed.ok) {
  throw new Error(parsed.value);
}

export const portfolioBundle = parsed.value;
export const portfolioEvaluator = ModelEvaluator.fromBundle(portfolioBundle);
